//! Rust stub generation.

use crate::plugin::{snake_case, upper_camel, MethodKind, ProtoFile, Service};

pub fn generate(file: &ProtoFile) -> String {
    let mut out = String::new();
    out.push_str("// @generated by protoc-gen-qrpc. Do not edit.\n");
    out.push_str(
        "// Messages are generated by the native protobuf plugin; qRPC stubs move bytes.\n\n",
    );
    out.push_str("use qrpc::{Client, ClientCall, ErrorCode, Server, Status};\n\n");
    for service in &file.services {
        write_service(&mut out, service);
    }
    out
}

fn write_service(out: &mut String, service: &Service) {
    let client_name = format!("{}Client", upper_camel(&service.name));
    let trait_name = format!("{}Service", upper_camel(&service.name));
    let register_name = format!("register_{}_service", snake_case(&service.name));
    let service_name = &service.full_name;

    out.push_str(&format!("pub struct {client_name} {{\n"));
    out.push_str("    inner: Client,\n");
    out.push_str("}\n\n");
    out.push_str(&format!("impl {client_name} {{\n"));
    out.push_str("    pub fn new(inner: Client) -> Self {\n");
    out.push_str("        Self { inner }\n");
    out.push_str("    }\n\n");
    for method in &service.methods {
        match method.kind {
            MethodKind::Unary => {
                out.push_str(&format!(
                    "    pub async fn {}(&self, request: Vec<u8>) -> Result<Vec<u8>, Status> {{\n",
                    method.rust_name
                ));
                out.push_str(&format!(
                    "        self.inner.unary(\"{}\", request).await\n",
                    method.route
                ));
                out.push_str("    }\n\n");
            }
            MethodKind::ServerStream => {
                out.push_str(&format!(
                    "    pub async fn {}(&self, request: Vec<u8>) -> Result<ClientCall, Status> {{\n",
                    method.rust_name
                ));
                out.push_str(&format!(
                    "        let mut call = self.inner.start_call(\"{}\").await?;\n",
                    method.route
                ));
                out.push_str("        call.send(request, true).await?;\n");
                out.push_str("        Ok(call)\n");
                out.push_str("    }\n\n");
            }
            MethodKind::ClientStream | MethodKind::BidiStream => {
                out.push_str(&format!(
                    "    pub async fn {}(&self) -> Result<ClientCall, Status> {{\n",
                    method.rust_name
                ));
                out.push_str(&format!(
                    "        self.inner.start_call(\"{}\").await\n",
                    method.route
                ));
                out.push_str("    }\n\n");
            }
        }
    }
    out.push_str("}\n\n");

    out.push_str(&format!(
        "pub trait {trait_name}: Clone + Send + Sync + 'static {{\n"
    ));
    for method in &service.methods {
        match method.kind {
            MethodKind::Unary => {
                out.push_str(&format!(
                    "    async fn {}(&self, request: Vec<u8>) -> Result<Vec<u8>, Status>;\n",
                    method.rust_name
                ));
            }
            MethodKind::ServerStream => {
                out.push_str(&format!(
                    "    async fn {}(&self, request: Vec<u8>) -> Result<Vec<Vec<u8>>, Status>;\n",
                    method.rust_name
                ));
            }
            MethodKind::ClientStream => {
                out.push_str(&format!(
                    "    async fn {}(&self, requests: Vec<Vec<u8>>) -> Result<Vec<u8>, Status>;\n",
                    method.rust_name
                ));
            }
            MethodKind::BidiStream => {
                out.push_str(&format!(
                    "    async fn {}(&self, requests: Vec<Vec<u8>>) -> Result<Vec<Vec<u8>>, Status>;\n",
                    method.rust_name
                ));
            }
        }
    }
    out.push_str("}\n\n");

    out.push_str(&format!(
        "pub fn {register_name}<S>(server: &mut Server, service: S)\n"
    ));
    out.push_str("where\n");
    out.push_str(&format!("    S: {trait_name},\n"));
    out.push_str("{\n");
    out.push_str(&format!(
        "    server.register_unary(\"{service_name}\", move |method, request| {{\n"
    ));
    out.push_str("        let service = service.clone();\n");
    out.push_str("        async move {\n");
    out.push_str("            match method.as_str() {\n");
    for method in &service.methods {
        if matches!(method.kind, MethodKind::Unary) {
            out.push_str(&format!(
                "                \"{}\" => service.{}(request).await,\n",
                method.route, method.rust_name
            ));
        }
    }
    out.push_str("                _ => Err(Status::new(ErrorCode::Unimplemented, \"unsupported streaming method in unary dispatcher\")),\n");
    out.push_str("            }\n");
    out.push_str("        }\n");
    out.push_str("    });\n");
    out.push_str("}\n\n");
}
